// معالجة وتطبيع مدخلات المستخدم وتجهيز المتغيرات السياقية
const body = $input.first().json.body || $input.first().json;

const userId = body.user_id || 'guest_' + Math.floor(100000 + Math.random() * 900000);
const conversationId = body.conversation_id || 'conv_' + Date.now();
const userMessage = (body.message || body.query || '').trim();
const city = body.city || 'عمّان';
const area = body.area || 'خلدا';
const favorites = (body.favorites && body.favorites.length) ? body.favorites.join(', ') : 'كوزمو، سي تاون، سيفوي، هايبرماكس';

const nowAmman = new Date().toLocaleString('ar-JO', { timeZone: 'Asia/Amman' });

return [{
  json: {
    user_id: userId,
    conversation_id: conversationId,
    user_message: userMessage,
    city: city,
    area: area,
    favorites: favorites,
    current_date_amman: nowAmman,
    timestamp: new Date().toISOString()
  }
}];

// أداة البحث في قاعدة عروض المتاجر الأردنية
