];

// تطبيق الفلاتر
let results = sampleOffers.filter(item => {
  if (retailer && !item.retailer.includes(retailer)) return false;
  if (brand && !item.brand.includes(brand)) return false;
  if (discountMin > 0 && item.discount_pct < discountMin) return false;
  if (query) {
    const matchName = item.product_name_ar.includes(query);
    const matchBrand = item.brand.includes(query);
    const matchRetailer = item.retailer.includes(query);
    if (!matchName && !matchBrand && !matchRetailer) return false;
  }
  return true;
});

if (results.length === 0) {
  results = sampleOffers.slice(0, 3);
}

return [{
  json: {
    total_found: results.length,
    offers: results
  }
}];

// أداة مقارنة الأسعار وسعر الوحدة
const product = $input.first().json.product || 'زيت';
